<script setup>
import {computed,ref} from 'vue';import {store,hoy,nombreCurso,cambiarEstado} from '../store';const error=ref('');const columnas=['Pendiente','En proceso','Completado'];const grupos=computed(()=>columnas.map(e=>({estado:e,tareas:store.tareas.filter(t=>t.estado===e).sort((a,b)=>a.fecha.localeCompare(b.fecha))})));async function mover(t,e){try{error.value='';await cambiarEstado(t,e)}catch(err){error.value=err.message}}
</script><template><div class="page-heading"><div><div class="eyebrow">ORGANIZACIÓN</div><h2>Tablero de planificación</h2><p>Gestiona el flujo de trabajo de tus actividades.</p></div><RouterLink to="/actividades?nueva=1" class="btn btn-primary">+ Nueva actividad</RouterLink></div><div v-if="error" class="alert alert-danger">{{error}}</div><div class="row g-3"><div v-for="g in grupos" :key="g.estado" class="col-lg-4"><div class="kanban"><h5>{{g.estado}} <span class="badge text-bg-light">{{g.tareas.length}}</span></h5><div v-if="!g.tareas.length" class="empty-state">Sin actividades</div><div v-for="t in g.tareas" :key="t.id" class="card p-3 mb-3"><div class="d-flex justify-content-between gap-2"><span class="small text-secondary">{{nombreCurso(t.curso)}}</span><span :class="['priority',t.prioridad.toLowerCase()]">{{t.prioridad}}</span></div><strong class="my-2">{{t.nombre}}</strong><small :class="t.fecha<hoy()&&t.estado!=='Completado'?'text-danger':'text-secondary'"><i class="bi bi-calendar3"></i> {{t.fecha}}</small><div class="mt-3"><select class="form-select form-select-sm" :value="t.estado" @change="mover(t,$event.target.value)" aria-label="Cambiar estado"><option v-for="e in columnas">{{e}}</option></select></div></div></div></div></div></template>